INSERT INTO lessons VALUES('phonics.short-vowels',1,'phonics-core-v1',1,'A',1,'短元音小石路','{"id":"short-vowels","title":"短元音小石路","grade":1,"kind":"sound","topicId":"phonics.cvc","rule":"先听完整单词，再看一个音怎样对应一块字母。这里选常见CVC词；字母名不是单词里的音。可以自己试着拆音，本页不把整词录音当作逐音素示范。","focus":"本组比较常见短元音a、e、i、o、u。","demos":[{"id":"mat","word":"mat","meaning":"垫子","tiles":["m","a","t"],"groups":[[0],[1],[2]],"focus":[1],"audioUrl":"/audio/phonics/8a6232d96d40611caf6ce415.wav"},{"id":"pet","word":"pet","meaning":"宠物","tiles":["p","e","t"],"groups":[[0],[1],[2]],"focus":[1],"audioUrl":"/audio/phonics/bb53558e6fac86781ff69b5d.wav"},{"id":"wig","word":"wig","meaning":"假发","tiles":["w","i","g"],"groups":[[0],[1],[2]],"focus":[1],"audioUrl":"/audio/phonics/20d0506ddecf62aa2fc79bc0.wav"},{"id":"hot","word":"hot","meaning":"热的","tiles":["h","o","t"],"groups":[[0],[1],[2]],"focus":[1],"audioUrl":"/audio/phonics/6355d63df78fe0c4ec8f6386.wav"},{"id":"rug","word":"rug","meaning":"小地毯","tiles":["r","u","g"],"groups":[[0],[1],[2]],"focus":[1],"audioUrl":"/audio/phonics/ebc9a96fadb3f18bb95efffa.wav"}],"items":40,"families":20,"roundSizes":[5,10,20]}');
INSERT INTO lessons VALUES('phonics.two-letter-sounds',1,'phonics-core-v1',1,'A',1,'两字母，一起发音','{"id":"two-letter-sounds","title":"两字母，一起发音","grade":1,"kind":"sound","topicId":"phonics.consonants","rule":"有的两个字母在这些词里一起对应一个音，如sh、ch、th、ng、ck。th在不同单词中可能发不同的音，不能说所有th都只有一种声音。先听整词，再观察本词的对应。","focus":"同一颜色下的字母一起承担一个音；不要逐字母念名称。","demos":[{"id":"shed","word":"shed","meaning":"小棚屋","tiles":["sh","e","d"],"groups":[[0],[1],[2]],"focus":[0],"audioUrl":"/audio/phonics/25522b090f8edc7c61274587.wav"},{"id":"chop","word":"chop","meaning":"切碎","tiles":["ch","o","p"],"groups":[[0],[1],[2]],"focus":[0],"audioUrl":"/audio/phonics/cf968dcf8f542ef315a4168b.wav"},{"id":"that","word":"that","meaning":"那个","tiles":["th","a","t"],"groups":[[0],[1],[2]],"focus":[0],"audioUrl":"/audio/phonics/f661016685727ae88b51b75d.wav"},{"id":"bang","word":"bang","meaning":"砰的一声","tiles":["b","a","ng"],"groups":[[0],[1],[2]],"focus":[2],"audioUrl":"/audio/phonics/9d548c81bb333d6fc3e658fa.wav"},{"id":"duck","word":"duck","meaning":"鸭子","tiles":["d","u","ck"],"groups":[[0],[1],[2]],"focus":[2],"audioUrl":"/audio/phonics/39df166b4f15e1c770516b17.wav"}],"items":40,"families":20,"roundSizes":[5,10,20]}');
INSERT INTO lessons VALUES('phonics.adjacent-consonants',1,'phonics-core-v1',2,'A',1,'辅音排排走','{"id":"adjacent-consonants","title":"辅音排排走","grade":2,"kind":"sound","topicId":"phonics.consonants","rule":"相邻辅音常各自保留一个音，如drum开头的d和r；这与shed的sh一起对应一个音不同。不要因为字母挨在一起，就把它们都算成一个音。","focus":"本组词开头的两个辅音分别保留，拼写时两个都要写。","demos":[{"id":"drum","word":"drum","meaning":"鼓","tiles":["d","r","u","m"],"groups":[[0],[1],[2],[3]],"focus":[0,1],"audioUrl":"/audio/phonics/b7a51e67230c256912b7e997.wav"},{"id":"brim","word":"brim","meaning":"帽檐","tiles":["b","r","i","m"],"groups":[[0],[1],[2],[3]],"focus":[0,1],"audioUrl":"/audio/phonics/6a658ece2fdbcfddca254acc.wav"},{"id":"spin","word":"spin","meaning":"旋转","tiles":["s","p","i","n"],"groups":[[0],[1],[2],[3]],"focus":[0,1],"audioUrl":"/audio/phonics/25d945abc5d0be6432c82c6d.wav"},{"id":"snip","word":"snip","meaning":"剪一小口","tiles":["s","n","i","p"],"groups":[[0],[1],[2],[3]],"focus":[0,1],"audioUrl":"/audio/phonics/0e63b4bcb1f0953e3179f678.wav"}],"items":40,"families":20,"roundSizes":[5,10,20]}');
INSERT INTO lessons VALUES('phonics.split-vowels',1,'phonics-core-v1',2,'A',1,'隔一格的元音伙伴','{"id":"split-vowels","title":"隔一格的元音伙伴","grade":2,"kind":"sound","topicId":"phonics.vowels","rule":"在这些词里，a_e、i_e、o_e隔着一个辅音一起标记长元音，末尾e不单独发一个音。不是每个词末e都服从同一规则，遇到新词仍要核对。","focus":"例如late里，a和末尾e用同一颜色；t仍是另一个音。","demos":[{"id":"late","word":"late","meaning":"迟到的","tiles":["l","a","t","e"],"groups":[[0],[1,3],[2]],"focus":[1],"audioUrl":"/audio/phonics/1d35478853374fe7b8e87c64.wav"},{"id":"ride","word":"ride","meaning":"骑行","tiles":["r","i","d","e"],"groups":[[0],[1,3],[2]],"focus":[1],"audioUrl":"/audio/phonics/9fccf1d40669b74b5f2e3773.wav"},{"id":"vote","word":"vote","meaning":"投票","tiles":["v","o","t","e"],"groups":[[0],[1,3],[2]],"focus":[1],"audioUrl":"/audio/phonics/0a3cd642119e0019de19655b.wav"}],"items":40,"families":20,"roundSizes":[5,10,20]}');
INSERT INTO lessons VALUES('phonics.vowel-teams',1,'phonics-core-v1',3,'A',1,'常见元音小搭档','{"id":"vowel-teams","title":"常见元音小搭档","grade":3,"kind":"sound","topicId":"phonics.vowels","rule":"在本组选词里，ai、ee、oa、oo各对应一个元音。相同拼写在别的词里可能不同，oo在别的词里可能有其他读法；不要把本组例子当成所有单词的唯一读法。","focus":"先听整词，再找连在一起的字母搭档。","demos":[{"id":"paint","word":"paint","meaning":"涂颜色","tiles":["p","ai","n","t"],"groups":[[0],[1],[2],[3]],"focus":[1],"audioUrl":"/audio/phonics/2699b5eeff07421813bb4ae6.wav"},{"id":"sheep","word":"sheep","meaning":"绵羊","tiles":["sh","ee","p"],"groups":[[0],[1],[2]],"focus":[1],"audioUrl":"/audio/phonics/9e1c3486fad42878352096d5.wav"},{"id":"toad","word":"toad","meaning":"蟾蜍","tiles":["t","oa","d"],"groups":[[0],[1],[2]],"focus":[1],"audioUrl":"/audio/phonics/13b420a601c1c3c985261c59.wav"},{"id":"spoon","word":"spoon","meaning":"勺子","tiles":["s","p","oo","n"],"groups":[[0],[1],[2],[3]],"focus":[2],"audioUrl":"/audio/phonics/defd8bc219e968694e598387.wav"}],"items":40,"families":20,"roundSizes":[5,10,20]}');
INSERT INTO lessons VALUES('phonics.meaning-parts',1,'phonics-core-v1',4,'A',1,'长词里的熟朋友','{"id":"meaning-parts","title":"长词里的熟朋友","grade":4,"kind":"meaning","topicId":"phonics.word-strategy","rule":"这一站按熟悉的小词理解复合词，如sunflower里的sun和flower。这里数的是有意义的词块，不是音素数或音节数；仍先听完整词，再结合语境理解。","focus":"两个有意义的词块，能帮你记住较长的拼写。","demos":[{"id":"sunflower","word":"sunflower","meaning":"向日葵","tiles":["sun","flower"],"groups":[[0],[1]],"focus":[0],"audioUrl":"/audio/phonics/d4f25da7a891fd409c609026.wav"},{"id":"teacup","word":"teacup","meaning":"茶杯","tiles":["tea","cup"],"groups":[[0],[1]],"focus":[0],"audioUrl":"/audio/phonics/f33192505855e900d1915251.wav"},{"id":"toothbrush","word":"toothbrush","meaning":"牙刷","tiles":["tooth","brush"],"groups":[[0],[1]],"focus":[0],"audioUrl":"/audio/phonics/10f978017f747cba702191e7.wav"},{"id":"popcorn","word":"popcorn","meaning":"爆米花","tiles":["pop","corn"],"groups":[[0],[1]],"focus":[0],"audioUrl":"/audio/phonics/4085e1018d73a5361e7b6d33.wav"}],"items":40,"families":20,"roundSizes":[5,10,20]}');
